def inputs(doc, scope):
    nodes = scope_nodes(doc, scope)
    inputs_list = []

    # Machine setup and failures/returns
    machines_node = next((n for n in nodes if "Machines" in n['title']), None)
    if machines_node:
        for idx, row in table_rows(machines_node):
            m_id = row['machine']
            # Initial Capacity
            inputs_list.append({
                "id": f"machine_init_{m_id}",
                "time": 0.0,
                "kind": "machine_setup",
                "entities": [m_id],
                "fields": {"CPU": int(row['CPU']), "memory": int(row['memory'])},
                "src": [machines_node['node_id'], idx]
            })
            # Failure
            fail_time = row['fails at']
            if fail_time != '-':
                inputs_list.append({
                    "id": f"machine_fail_{m_id}",
                    "time": float(fail_time),
                    "kind": "machine_failure",
                    "entities": [m_id],
                    "fields": {},
                    "src": [machines_node['node_id'], idx]
                })
            # Return
            ret_time = row['returns at']
            if ret_time != '-':
                inputs_list.append({
                    "id": f"machine_return_{m_id}",
                    "time": float(ret_time),
                    "kind": "machine_return",
                    "entities": [m_id],
                    "fields": {},
                    "src": [machines_node['node_id'], idx]
                })

    # Task submissions
    log_node = next((n for n in nodes if "Task log" in n['title']), None)
    if log_node:
        for idx, row in table_rows(log_node):
            if row['event'] == 'submit':
                t_id = row['task']
                inputs_list.append({
                    "id": f"task_submit_{t_id}",
                    "time": float(row['time']),
                    "kind": "task_submission",
                    "entities": [t_id, row['job']],
                    "fields": {
                        "priority": int(row['priority']),
                        "CPU": int(row['CPU']),
                        "memory": int(row['memory']),
                        "run_time": int(row['run time'])
                    },
                    "src": [log_node['node_id'], idx]
                })

    return inputs_list

def outcomes(doc, scope):
    nodes = scope_nodes(doc, scope)
    outcomes_list = []

    # Task log events
    log_node = next((n for n in nodes if "Task log" in n['title']), None)
    if log_node:
        for idx, row in table_rows(log_node):
            event = row['event']
            if event in ['start', 'finish', 'evict', 'fail']:
                t_id = row['task']
                m_id = row['machine']
                outcomes_list.append({
                    "time": float(row['time']),
                    "kind": f"task_{event}",
                    "entities": [t_id] + ([m_id] if m_id != '-' else []),
                    "value": None,
                    "src": [log_node['node_id'], idx]
                })

    # Longest waits from Events list
    events_node = next((n for n in nodes if "Events" in n['title']), None)
    if events_node:
        for idx, line in enumerate(events_node['lines']):
            match = re.search(r"longest wait[s]? was (\d+) seconds for task (T\d+)", line)
            if match:
                wait_time = int(match.group(1))
                t_id = match.group(2)
                outcomes_list.append({
                    "time": 1200.0,
                    "kind": "longest_wait",
                    "entities": [t_id],
                    "value": wait_time,
                    "src": [events_node['node_id'], idx]
                })

    # Final state
    running_node = next((n for n in nodes if "Queue at window end: Tasks running" in n['title']), None)
    if running_node:
        for idx, row in table_rows(running_node):
            outcomes_list.append({
                "time": 1200.0,
                "kind": "final_state_running",
                "entities": [row['task']],
                "value": float(row['remaining']),
                "src": [running_node['node_id'], idx]
            })

    waiting_node = next((n for n in nodes if "Queue at window end: Tasks waiting" in n['title']), None)
    if waiting_node:
        for idx, row in table_rows(waiting_node):
            outcomes_list.append({
                "time": 1200.0,
                "kind": "final_state_waiting",
                "entities": [row['task']],
                "value": None,
                "src": [waiting_node['node_id'], idx]
            })

    return outcomes_list

